parameters.jsCode:
const raw = String($input.item.json.output ?? '');

const fallback = (reason) => ({
  reasoning_steps: ["PARSE FAILED - " + reason],
  sender: "unknown",
  topic: null,
  proposed_time: null,
  suggested_slot: null,
  duration_minutes: null,
  urgency: "medium",
  decision: "need_more_info",
  missing_info: ["Could not parse AI response: " + reason],
  calendar_check: "",
  draft_response: null,
  event_start: null,
  event_end: null,
  raw_output: raw.slice(0, 1000)
});

let parsed;
try {
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON object in agent output');
  parsed = JSON.parse(cleaned.slice(start, end + 1));
  // a stray tool-call blob is also valid JSON - reject anything that is not our schema
  if (!parsed.decision || !parsed.sender) {
    throw new Error('JSON found but wrong shape (keys: ' + Object.keys(parsed).join(', ') + ')');
  }
} catch (e) {
  parsed = fallback(e.message);
}

// the email and the gate read these - never let them be undefined
parsed.reasoning_steps = Array.isArray(parsed.reasoning_steps) ? parsed.reasoning_steps : [];
parsed.missing_info = Array.isArray(parsed.missing_info) ? parsed.missing_info : [];

return { json: parsed };
